function validate(d) {
const errors=[]; const fail=s=>errors.push(s); 
function shape(v,t,p) {
if(t.endsWith("?")){if(v===null)return;t=t.slice(0,-1);}
if(t.startsWith("[")){if(!Array.isArray(v)){fail(p+" array");return;}v.forEach((x,i)=>shape(x,t.slice(1,-1),p+"["+i+"]"));const vals=v.map(x=>typeof x==="object"?(t==="[Recheck]"?x.kind+":"+x.id:x?.id): x).filter(x=>x!=null);if(new Set(vals).size!==vals.length)fail(p+" duplicates");return;}
if(schema[t]){if(!v||typeof v!=="object"||Array.isArray(v)){fail(p+" object");return;}const fields=Object.fromEntries(schema[t].split(" ").map(x=>{const at=x.indexOf(":");return [x.slice(0,at),x.slice(at+1)];}));if(Object.keys(v).sort().join()!=Object.keys(fields).sort().join())fail(p+" exact fields");for(const[k,st]of Object.entries(fields))shape(v[k],st,p+"."+k);return;}
const ok=t==="str"?typeof v==="string":t==="id"?typeof v==="string"&&v.length>0:t==="bool"?typeof v==="boolean":t==="uint"?Number.isInteger(v)&&v>=0:t==="pos"?Number.isInteger(v)&&v>0:t==="percent"?typeof v==="number"&&v>=0&&v<=100:t==="commit"?typeof v==="string"&&/^[a-f0-9]{40}([a-f0-9]{24})?$/.test(v):t==="sha"?typeof v==="string"&&/^[a-f0-9]{64}$/.test(v):t==="time"?typeof v==="string"&&/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z$/.test(v)&&!Number.isNaN(Date.parse(v)):t==="availability"?["available","unavailable","redacted"].includes(v):t==="format"?v==="sp-bp-checkpoint/v1":t.split("|").includes(v);if(!ok)fail(p+" type "+t);
}
shape(d,"Top","$");if(errors.length)return{valid:false,acceptable:false,errors};
const groups=["issues","pull_requests","authorities","requirements","criteria","dispositions","coverage","evaluations","evidence"],maps={};for(const g of groups)maps[g]=new Map(d[g].map(x=>[x.id,x]));
const nativeIds=new Set([...maps.issues.keys(),...d.scope.excluded_ids,...d.scope.external_records.map(x=>x.id)]), prIds=new Set([...maps.pull_requests.keys(),...d.scope.excluded_ids,...d.scope.external_records.map(x=>x.id)]);
const ref=(ids,map,where)=>{for(const id of ids)if(!map.has(id))fail(where+" unresolved "+id);};const equal=(a,b)=>[...a].sort().join()==[...b].sort().join();
if(!equal(d.scope.issue_ids,d.issues.map(x=>x.id)))fail("scope node membership");
if(Date.parse(d.capture.finished_at)<Date.parse(d.capture.started_at))fail("capture time ordering");
const codes=d.issues.filter(x=>x.backplane_record).map(x=>x.backplane_record.namespace+":"+x.backplane_record.code);if(new Set(codes).size!==codes.length)fail("duplicate code");
for(const a of d.authorities)ref(a.approval_ids,maps.authorities,a.id);
for(const i of d.issues){ref([i.parent_id,...(i.child_ids??[]),...(i.blocked_by_ids??[]),...(i.blocking_ids??[])].filter(Boolean),nativeIds,i.id);ref(i.closing_pr_ids??[],prIds,i.id);ref(i.accepted_evaluation_ids,maps.evaluations,i.id);if(i.backplane_record)ref(i.backplane_record.authority_ids,maps.authorities,i.id);for(const c of i.child_ids??[])if(maps.issues.has(c)&&maps.issues.get(c).parent_id!==i.id)fail("hierarchy reciprocity");if(i.parent_id&&maps.issues.has(i.parent_id)&&maps.issues.get(i.parent_id).child_ids!==null&&!maps.issues.get(i.parent_id).child_ids.includes(i.id))fail("parent reciprocity");for(const b of i.blocked_by_ids??[])if(maps.issues.has(b)&&maps.issues.get(b).blocking_ids!==null&&!maps.issues.get(b).blocking_ids.includes(i.id))fail("dependency reciprocity");if(i.sub_issues_summary&&i.sub_issues_summary.total!==(i.child_ids?.length??0)&&d.capture.status==="complete")fail("sub issue total");for(const evId of i.accepted_evaluation_ids){const ev=maps.evaluations.get(evId);if(ev&&maps.criteria.get(ev.criterion_id)?.issue_id!==i.id)fail("accepted pointer owner");}}
for(const p of d.pull_requests)ref(p.closing_issue_ids,nativeIds,p.id);
for(const r of [...d.requirements,...d.criteria]){ref([r.authority_id],maps.authorities,r.id);const a=maps.authorities.get(r.authority_id);if(a&&a.revision!==r.authority_revision&&!d.capture.rechecks.some(x=>x.id===a.id&&x.result==="reconciled"&&x.approval_ids.length))fail("authority revision");if(r.issue_id)ref([r.issue_id],maps.issues,r.id);if(r.requirement_ids)ref(r.requirement_ids,maps.requirements,r.id);}
for(const c of d.coverage){ref([c.issue_id,...c.contribution_issue_ids],nativeIds,c.id);ref([c.criterion_id],maps.criteria,c.id);ref(c.requirement_ids,maps.requirements,c.id);ref(c.pr_ids,prIds,c.id);if(maps.criteria.get(c.criterion_id)?.issue_id!==c.issue_id)fail("coverage owner");if(c.contribution_issue_ids.length>1&&!c.combined_result_owner)fail("combined owner");}
for(const x of d.dispositions){ref([x.parent_issue_id,...x.child_issue_ids],nativeIds,x.id);ref(x.requirement_ids,maps.requirements,x.id);ref(x.evidence_ids,maps.evidence,x.id);ref(x.approval_ids,maps.authorities,x.id);if(["deferred","excluded"].includes(x.disposition)&&!x.approval_ids.some(id=>maps.authorities.get(id)?.availability==="available"))fail("disposition approval");}
for(const e of d.evaluations){ref([e.criterion_id],maps.criteria,e.id);ref(e.requirement_ids,maps.requirements,e.id);ref(e.evidence_ids,maps.evidence,e.id);ref(e.review_approval_ids,maps.authorities,e.id);const c=maps.criteria.get(e.criterion_id);if(e.result==="SATISFIED"&&e.applicability==="current"){if(!c||!equal(e.requirement_ids,c.requirement_ids)||!e.verified_commit||e.verified_commit!==c.delivery_commit||e.remaining_contributions.length||e.limitations.length)fail("current evaluation input");if(!e.evidence_ids.some(id=>{const ev=maps.evidence.get(id);return ev?.kind==="verification"&&ev.availability==="available"&&ev.verified_commit===e.verified_commit&&(ev.content||ev.revision);} ))fail("verification evidence");if(!e.review_approval_ids.some(id=>maps.authorities.get(id)?.availability==="available"))fail("review approval");}}
for(const i of d.issues)for(const [field,name]of [["labels","labels"],["assignees","assignees"],["child_ids","subIssues"],["blocked_by_ids","blockedBy"],["blocking_ids","blocking"],["closing_pr_ids","closingPRReferences"]])if(i[field]===null){const co=d.scope.collections.find(x=>x.name===name&&x.owner_id===i.id);if(d.capture.status!=="partial"||d.scope.complete||!i.limitations.length||!co||co.complete||co.expected_total!==null||co.pages.length)fail("unavailable native collection diagnostic guard "+field);}
if(d.capture.status==="complete"){if(!d.scope.complete)fail("complete scope");for(const co of d.scope.collections){const members=co.pages.flatMap(p=>p.record_ids);if(!co.complete||!co.pages.length||co.pages[0].cursor_in!==null||co.pages.at(-1).has_next_page!==false||new Set(members).size!==members.length||(co.expected_total!==null&&co.expected_total!==members.length))fail("pagination "+co.name);for(let n=1;n<co.pages.length;n++)if(co.pages[n-1].has_next_page!==true||!co.pages[n].cursor_in||co.pages[n].cursor_in!==co.pages[n-1].cursor_out)fail("cursor continuity");}
for(const i of d.issues)for(const name of ["subIssues","blockedBy","blocking","closingPRReferences","labels","assignees"]){const col=d.scope.collections.find(x=>x.name===name&&x.owner_id===i.id);if(!col)fail("missing collection "+name);else{const ids=name==="subIssues"?i.child_ids:name==="blockedBy"?i.blocked_by_ids:name==="blocking"?i.blocking_ids:name==="closingPRReferences"?i.closing_pr_ids:name==="labels"?i.labels?.map(x=>x.id??x.name):i.assignees;if(ids===null||ids===undefined||!equal(ids,col.pages.flatMap(x=>x.record_ids)))fail("collection membership "+name);}}
for(const g of ["issues","pull_requests"]){const name=g==="issues"?"issues":"pullRequests";if(!d.scope.collections.some(x=>x.name===name&&equal(d[g].map(x=>x.id),x.pages.flatMap(p=>p.record_ids))))fail("missing collection "+name);}
for(const [g,kind]of [["issues","issue"],["authorities","authority"],["evidence","evidence"]])for(const x of d[g])if(!d.capture.rechecks.some(r=>r.kind===kind&&r.id===x.id))fail("missing recheck "+x.id);
if(!d.capture.rechecks.some(x=>x.kind==="graph"))fail("graph recheck");for(const r of d.capture.rechecks){if(["changed","unavailable"].includes(r.result))fail("source "+r.result);if(r.result==="unchanged"&&(r.initial_revision===null||r.initial_revision!==r.final_revision))fail("unchanged revision");if(r.result==="reconciled"&&!r.approval_ids.some(id=>maps.authorities.get(id)?.availability==="available"))fail("reconciliation approval");}
for(const x of [...d.authorities,...d.evidence])if(x.availability!=="available")fail("required material unavailable");
if(d.capture.mode==="integrated"){if(!d.project||d.project.availability!=="available")fail("Project unavailable");else{if(d.project.field_definitions===null||d.project.items===null)fail("Project collection unavailable");if(!d.capture.rechecks.some(x=>x.kind==="project"&&x.id===d.project.id))fail("Project recheck");for(const item of d.project.items??[]){const i=maps.issues.get(item.content_id);for(const fv of item.fields??[]){const f=(d.project.field_definitions??[]).find(x=>x.id===fv.field_id);if(!f)fail("Project field ref");if(f?.name==="Satisfaction"&&i){const accepted=i.accepted_evaluation_ids.map(x=>maps.evaluations.get(x));const expected=accepted.length&&accepted.every(x=>x?.result==="SATISFIED"&&x.applicability==="current")?"SATISFIED":"UNKNOWN";if(fv.text!==expected)fail("Project projection contradiction");}}}}}else if(d.project!==null)fail("issues-only Project identity");
}
return {valid:errors.length===0,acceptable:errors.length===0&&d.capture.status==="complete",errors};
}
